"""Fitness function that determines on the fly whether to use
    a sampling algorithm or not.
    """
def _FunctionSelector(
    population: Any,
    N: Any,
    samples: Any,
    stdFunction: Any,
    sampleFunction: Any,
    baseParams: Any
) -> object {
    L = len(population);
    combinations = L ** N;
    if (samples < 1.0) {
        samples = int(((combinations * samples) + 0.5));
    }
    if (samples == 0) {
        samples = 1;
    }
    if (samples < combinations) {
        return sampleFunction(population, *(baseParams + (samples, )));
    } else {
        return stdFunction(population, *baseParams);
    }
}

